-- Physically order the orders heap by order_date. Without this the random
-- date layout makes an index scan look more expensive than a seq scan at this
-- size, and the planner ignores the index. CLUSTER is a one-time bulk-load step.
CREATE INDEX orders_order_date_tmp_idx ON orders (order_date);
CLUSTER orders USING orders_order_date_tmp_idx;
DROP INDEX orders_order_date_tmp_idx;

